settings.query:
MATCH (c:Concept)
WITH count(c) AS total,
     sum(CASE WHEN c.description IS NOT NULL AND c.description <> "" THEN 1 ELSE 0 END) AS has_desc
RETURN toFloat(has_desc) / total AS DescriptionCompleteness
// Scoped to :Concept only — :ConceptTarget intentionally has no description property
// Target: >= 0.90
